SELECT
	ORDERED_DATE as orderedDate
FROM SHOP_SALES_API
WHERE SHOP_TYPE = #{shopType}
AND SHOP_ID = #{shopId}
ORDER BY ORDERED_DATE DESC LIMIT 1

SELECT
	UPD_DATE as updDate
FROM SHOP_SALES_API
WHERE SHOP_TYPE = #{shopType}
AND SHOP_ID = #{shopId}
ORDER BY UPD_DATE DESC LIMIT 1

SELECT
	INPUT_DATE as inputDate
FROM SHOP_SALES_API
WHERE SHOP_TYPE = #{shopType}
AND SHOP_ID = #{shopId}
ORDER BY INPUT_DATE DESC LIMIT 1

SELECT
	payment_amount
FROM
	SHOP_SALES_API
WHERE
	shop_type = #{shopType}
  AND shop_id = #{shopId}
  AND order_no = #{orderNo}
